# -*- coding: utf-8 -*-
"""Merge discovery JSONL files into domain lists (one line per unique domain) with the first city that found it."""
import json, glob, re, urllib.parse, collections, sys
EXCL = re.compile(r"(^|\.)(jusbrasil|facebook|instagram|linkedin|youtube|twitter|x\.com|tiktok|wikipedia|google|bing|yahoo|oab\.org\.br|oab[a-z]{2}\.org\.br|gov\.br|jus\.br|reclameaqui|apontador|telelistas|listamais|listaamarela|guiamais|hotfrog|cylex|yelp|foursquare|solutudo|infoisinfo|acharadvogados|advogalia|lawzana|migalhas|conjur|estadao|globo\.com|uol\.com\.br|terra\.com\.br|r7\.com|folha|lawyers\.com|avvo|justia|findlaw|martindale|superlawyers|hg\.org|lawyerlegion|legal500|chambers|nolo\.com|upcounsel|expertise\.com|thumbtack|bark\.com|yell\.com|trustpilot|glassdoor|indeed|catho|vagas\.com|gupy|mercadolivre|amazon|apple\.com|microsoft|medium\.com|escavador|consultaprocessos|dicio|significados|cnj\.jus|tjsp|stj|stf|trf|tst|trt|mpf|receita|caixa|bb\.com\.br|bradesco|itau|santander|nubank|sympla|hotmart|udemy|coursera|encontra[a-z]+\.com\.br|advocaciascuritiba|lista|guia|diretorio|directory|wikihow|quora|reddit|pinterest|vimeo|spotify|yellowpages|bbb\.org|mapquest|manta\.com|zoominfo|crunchbase|bloomberg|forbes|nytimes|bbc|gov\.uk|canada\.ca|gc\.ca|europa\.eu|\.gov$|\.gov\.|\.edu$|\.edu\.|lawsociety|bar\.org|barassociation|aila\.org|ailalawyer|cila\.co|capic|migratio|myconsultant|canadim|moving2canada|visaplace|boundless|uscis|ircc|homeaffairs|sef\.pt|aima\.gov|portaldasfinancas|idealista|jobs|vagas|emprego|site123|webnode|blogspot|wordpress\.com|tumblr|godaddysites|squarespace\.com|weebly|carrd|linktr|bit\.ly|goo\.gl|whatsapp|wa\.me|telegram|olx|zapimoveis|vivareal|booking|airbnb|tripadvisor|britannica|dictionary|cambridge|merriam|law\.com|lexology|mondaq|jdsupra|lawfirms|lawyerdirectory|lawyersdb|expertlaw|justanswer|legalmatch|lawinfo|attorneys\.com|lawyer\.com|superpages|whitepages|opencorporates|dnb\.com|bizapedia|buzzfile|chamberofcommerce|alignable|angi|homeadvisor|nextdoor|patch\.com|craigslist|ebay|etsy|fb\.com|threads\.net|flickr|melhores|10melhores|comercio|noticias|guiatelefone|eguias|telefone|empresas|cnpj|econodata|casadosdados|cadastroempresa|consultasocio|solutudo|empresaqui|kompass|cortex|serasa|boavista|yelp|clutch|sortlist|glassdoor|catho|infojobs|jooble|neuvoo|jobatus|trovit|mitula|zapimoveis|wixsite|wix\.com|canva\.site|my\.canva|notion\.site|github|gitlab|academia\.edu|researchgate|scielo|periodicos|revistas|jusbrasil|direitonet|ambito|ibdfam|ibccrim|conjur|migalhas|jota\.info|valor\.globo|exame|infomoney|istoe|veja|cnnbrasil|band|sbt|record|lawtech|lexlegal|juridico\.ai|advbox|astrea|projuris|themis|kurier|aurum|easyjur|lawoffice\.com|clio|mycase|docketwise|statusinvest|investidor10|investing|anbima|cvm|bcb|ipea|ibge|sebrae|senac|sesi|fiesp|cni|cnc|cnseg|fenaseg|febraban|abrasel|abras|abinee|abit|abimaq|abiquim|abrace|abrafarma|abradee|abcem|apex|bndes|finep|cnpq|capes|inep|mec|anvisa|ans|aneel|anatel|ancine|antt|anac|anp|ana\.gov|ibama|icmbio|funai|incra|inss|dataprev|caixa|bb\.com|correios|petrobras|eletrobras|vale\.com|embraer|natura|ambev|jbs|brf|gerdau|usiminas|csn|suzano|klabin|weg|magalu|americanas|casasbahia|viavarejo|submarino|shoptime|netshoes|dafiti|ifood|rappi|uber|99app|loggi|mercadopago|pagseguro|stone|cielo|rede|getnet|picpay|inter|c6bank|original|bmg|pan|safra|votorantim|btg|xp|rico|clear|modal|guide|toro|easynvest|warren|nuinvest|avenue)($|\.)", re.I)
def dom(u):
    h = urllib.parse.urlparse(u).netloc.lower().split(":")[0]
    return h[4:] if h.startswith("www.") else h
for mode in ("BR", "INT"):
    doms = collections.OrderedDict(); n = 0
    for f in sorted(glob.glob(f"disc_{mode}*.jsonl")):
        for l in open(f, encoding="utf-8"):
            try: r = json.loads(l)
            except Exception: continue
            n += 1; d = dom(r["url"])
            if not d or "." not in d or EXCL.search(d) or len(d) > 60: continue
            if d not in doms: doms[d] = {"domain": d, "cc": r["cc"], "city": r["city"], "uf": r["uf"], "q": r["q"]}
    with open(f"domains_{mode}.jsonl", "w", encoding="utf-8") as fh:
        for v in doms.values(): fh.write(json.dumps(v, ensure_ascii=False) + "\n")
    print(mode, "resultados:", n, "domínios únicos:", len(doms))
